<script lang="ts">import {onMount} from 'svelte';let provider='anthropic';let key='';let configured=false;let message='';onMount(async()=>{const s=await (await fetch('/api/settings')).json();provider=s.provider;configured=s.configured});async function save(){const r=await fetch('/api/settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({provider,api_key:key})});message=r.ok?'Settings saved.':(await r.json()).detail;key=''}</script>
<section class="page"><h1>Settings</h1><p>{configured?'API key configured.':'API key is missing — add one to enable generation.'}</p><label>Provider<select bind:value={provider}><option value="anthropic">Anthropic</option><option value="google">Google</option></select></label><label>API key<input type="password" bind:value={key} autocomplete="off"/></label><button on:click={save}>Save</button>{#if message}<p>{message}</p>{/if}</section><style>.page{padding:32px;max-width:600px;margin:auto;display:flex;flex-direction:column;gap:16px}.page label{display:flex;flex-direction:column;gap:8px}.page input,.page select{background:#1e1c27;color:#edecee;border:1px solid #29263c;padding:10px}.page button{background:#a277ff;border:0;border-radius:10px;padding:10px}</style>
